/// <summary>
///     Data Controller class for <c>AVASalesQuotationRequestStatsReport</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Controller class for the <c>AVASalesQuotationRequestStatsReport</c> SSRS Report.
/// </remarks>
internal final class AVASalesQuotationRequestStatsReportController extends  SrsReportRunController
{
    Args                        clsArgs;
    SalesQuotationTable         clsSalesQuotationTable;
    KCS_KBVRequestTable         clsKCS_KBVRequestTable;
    KCS_KBVBuildingProjectTable clsKCS_KBVBuildingProjectTable;
    smmBusRelTable              clsSmmBusRelTable;
    CustTable                   clsCustTable;
    boolean                     clsPreviewMode;

}

