/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVASalesQuotationRequestStatsReportController controller;

    controller = AVASalesQuotationRequestStatsReportController::newFromArgs(_args);

    controller.parmReportName(ssrsReportStr(AVASalesQuotationRequestStatsReport, Report));
    controller.parmDialogCaption("@NDX:NXABPRequestStatistics");
    controller.startOperation();
}

/// <summary>
///    AVA <c>prePromptModifyContract</c> method.
/// </summary>
protected void prePromptModifyContract()
{
    AVASalesQuotationRequestStatsReportContract contract;

    clsPreviewMode = false;

    contract = this.parmReportContract().parmRdpContract();

    contract.parmQuotationId(clsSalesQuotationTable.QuotationId);
    contract.parmCustAccount(clsCustTable.AccountNum);
    contract.parmSmmBusRelAccount(clsSmmBusRelTable.BusRelAccount);
    contract.parmKCS_KBVRequestID(clsKCS_KBVRequestTable.KCS_KBVRequestID);
    contract.parmKCS_KBVBuildingProjectID(clsKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);

    contract.parmPrintMode(SalesTableMode::Simple);

    // Set the target print destination to Screen if we are previewing the report.
    if(this.parmArgs())
    {
        if(this.parmArgs().menuItemName() == menuItemActionStr(AVASalesQuotationRequestStatsReportActionPreview))
        {
            clsPreviewMode = true;
        }
        else if(this.parmArgs().menuItemName() == menuItemActionStr(AVASalesQuotationRequestStatsReportAction))
        {
            clsPreviewMode = false;
        }
        else if(this.parmArgs().menuItemName() == menuItemOutputStr(AVASalesQuotationRequestStatsReportOutput))
        {
            clsPreviewMode = false;
        }
    }

    if (clsPreviewMode)
    {
        this.parmReportContract().parmPrintSettings().printMediumType(SRSPrintMediumType::Screen);
    }

    // Don't show the report dialog if Preview
    // and don't save to SysLastValue either.
    this.parmShowDialog(!clsPreviewMode);
    this.parmLoadFromSysLastValue(!clsPreviewMode);
}

/// <summary>
///    AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>AVASalesQuotationRequestStatsReportController</c> as return value
/// </returns>
public static AVASalesQuotationRequestStatsReportController newFromArgs(Args _args)
{
    AVASalesQuotationRequestStatsReportController   locController;
    Common                                          locCommon;
    SalesQuotationTable                             locSalesQuotationTable;
    KCS_KBVRequestTable                             locKCS_KBVRequestTable;
    KCS_KBVBuildingProjectTable                     locKCS_KBVBuildingProjectTable;
    smmBusRelTable                                  locsmmBusRelTable;
    CustTable                                       locCustTable;

    //locController = new AVASalesQuotationRequestStatsReportController();
    locController = AVASalesQuotationRequestStatsReportController::construct();
    locController.parmArgs(_args);
    locController.parmLoadFromSysLastValue(false);

    if(_args)
    {
        if(_args.record().RecId)
        {
            locCommon = _args.record();

            switch(locCommon.TableId)
            {
                case tableNum(SalesQuotationTable):
                    locSalesQuotationTable = locCommon;
                    locController.parmSalesQuotationTable(locSalesQuotationTable);
                    break;

                case tableNum(KCS_KBVRequestTable):
                    locKCS_KBVRequestTable = locCommon;
                    locController.parmKCS_KBVRequestTable(locKCS_KBVRequestTable);
                    break;

                case tableNum(KCS_KBVBuildingProjectTable):
                    locKCS_KBVBuildingProjectTable = locCommon;
                    locController.parmKCS_KBVBuildingProjectTable(locKCS_KBVBuildingProjectTable);
                    break;

                case tableNum(CustTable):
                    locCustTable = locCommon;
                    locController.parmCustTable(locCustTable);
                    break;

                case tableNum(smmBusRelTable):
                    locsmmBusRelTable = locCommon;
                    locController.parmSmmBusRelTable(locsmmBusRelTable);
                    break;

                default:
                    locController.parmLoadFromSysLastValue(true);
            }
        }
        else
        {
            locController.parmLoadFromSysLastValue(true);
        }
    }
    return locController;
}
